if (!msg.payload || !msg.payload.list || msg.payload.list.length === 0) {
    node.error("No location service linked to the inspected services of inspection: " +
        ((msg.inspectionPlan && msg.inspectionPlan.inspectionId) ? msg.inspectionPlan.inspectionId : "?"), msg);
    return null;
}

  let prov = msg.payload.list[0];

  // if location service has a point of contact associated to it, save the contact id  
  if (prov.pointOfContactId) {
    msg.inspectionPlan.provider["contact"] = {};
    msg.inspectionPlan.provider.contact = {
      "id" : prov.pointOfContactId,
      "name" : prov.pointOfContactName
    }
  }

  msg.inspectionPlan.provider["services"] = [];

for (var provider of msg.payload.list) {
  msg.inspectionPlan.provider.services.push({
    "name" : provider.shortName,
    "specialties" : msg.locationServiceObj[provider.id]
  });
}

msg.payload = msg.inspectionPlan

return msg;

msg.entity = "Person";
msg.entityData = {
    "_or" : {
      "serviceProviderId" : msg.inspectionPlan.provider.id,
      "id" : msg.inspectionPlan.provider.contact?.id || null }
};
msg.entitySelect = "id,name,workPosition,serviceProviderName";
return msg;

const person = (msg.payload && msg.payload.list) ? msg.payload.list[0] : null;
if (!person) {
    node.error("No contact person found for provider: " +
        ((msg.inspectionPlan && msg.inspectionPlan.provider) ? msg.inspectionPlan.provider.id : "?"), msg);
    return null;
}
msg.inspectionPlan.provider.contact = {
    "name" : person.name,
    "position" : person.workPosition
};

return msg;

msg.specialtyIds = msg.payload.list.map((x) => ({ 
    "id" : x.id,
    "serviceId" : x.inspectedServiceId 
}));
return msg;

msg.entity = "InspectedSpecialtyInspector";
msg.entityData = {"inspectedSpecialtyId" : msg.specialtyIds.map((x) => x.id)};
msg.entitySelect = "inspectedSpecialtyId,inspectedSpecialtyName,inspectorName";
return msg;

let serviceObj = {};
let serviceId = {};
let thisOne = 0;
for (var inspector of msg.payload.list) {
    serviceId = msg.specialtyIds.find((x) => x.id == inspector.inspectedSpecialtyId);
    if (!serviceObj[serviceId.serviceId]) {
        serviceObj[serviceId.serviceId] = [];
    }
    thisOne = serviceObj[serviceId.serviceId].findIndex( (x) => x.name == inspector.inspectedSpecialtyName );
    if (thisOne == -1) {
        serviceObj[serviceId.serviceId].push({
            "name" : inspector.inspectedSpecialtyName,
            "inspectors" : [inspector.inspectorName]
        })
    } else {
        serviceObj[serviceId.serviceId][thisOne].inspectors.push(
            inspector.inspectorName
        );
    }
}

msg.serviceObj = serviceObj;

return msg;

msg.entity = "InspectedService";
msg.entityData = {"id" : msg.specialtyIds.map((x) => x.serviceId)};
msg.entitySelect = "id,locationServiceId"
return msg;

let locationServiceObj = {}
for (var service of msg.payload.list) {
    locationServiceObj[service.locationServiceId] = msg.serviceObj[service.id];
}
msg.locationServiceObj = locationServiceObj;
return msg;

msg.entity = "LocationService";
var ids = Object.keys(msg.locationServiceObj);
if (ids.length === 0) {
    msg.payload = { list: [] };
    return msg;
}
msg.entityData = { "id": ids };
msg.entitySelect = "id,serviceProviderName,shortName,serviceProviderId,pointOfContactId,pointOfContactName";
return msg;

const OPENING = "Opening Meeting";
const CLOSING = "Closing Meeting"
function mapSchedule(schedule) {
    switch (schedule.name) {
        case OPENING: 
//          msg.inspectionPlan.openingDateTime = schedule.startDate;
          return undefined;
        case CLOSING:
//          msg.inspectionPlan.closureDateTime = schedule.startDate;
          return undefined;
        default:
          return ({
            "name" : schedule.name,
            "place" : schedule.place,
            "startDateTime" : schedule.startDateTime,
            "endDateTime" : schedule.endDateTime
          })
    }
}

msg.inspectionPlan.openingDateTime = msg.payload.list.find((x) => x.name == OPENING).startDateTime;
msg.inspectionPlan.closureDateTime = msg.payload.list.find((x) => x.name == CLOSING).startDateTime;
msg.inspectionPlan["schedules"] = msg.payload.list
                                    .map(mapSchedule)
                                    .filter((x) => (x !== undefined));


return msg;

// The caller asked for the plan, not for this status update, and the update rewrites msg
// (entity / entityId / updateData) for the AtroCore call. Keep the generation result aside
// for the response; without it the response carried the updateEntity result.
msg.planGenerationResult = msg.payload;

var inspectionId = msg.inspectionId || (msg.inspectionPlan && msg.inspectionPlan.inspectionId);
if (!inspectionId) {
    node.error("No inspection ID for status update", msg);
    return null;
}

msg.entity = "Inspection";
msg.entityId = inspectionId;
msg.updateData = { status: "Planned" };
return msg;

msg.entity = "Inspection";
msg.entityData = {
    "inspectedProviderId" : msg.providerId
    };
msg.entitySelect = null;
return msg;

if (!msg.payload || !msg.payload.list || msg.payload.list.length === 0) {
    node.error("No inspection found for site visit: " + (msg.siteVisitId || msg.inspectionCode), msg);
    return null;
}
msg.inspectionPlan["inspectionNo"] = msg.payload.list[0].code;
msg.inspectionPlan["scope"] = msg.payload.list[0].scope; 
msg.inspectionPlan["objective"] = msg.payload.list[0].objective;
msg.inspectionId = msg.payload.list[0].id;

return msg;

msg.entity = "SiteVisit";
msg.entityData = { "code" : msg.inspectionCode };
return msg;

if (!msg.payload || !msg.payload.list || msg.payload.list.length === 0) {
    // An unknown ?siteVisit= code leaves the SiteVisit query empty; indexing list[0] threw a
    // TypeError whose message reached the client instead of naming what was not found.
    node.error("No site visit found for code: " + msg.inspectionCode, msg);
    return null;
}
msg.inspectionPlan = {
    //"inspectionId" : msg.payload.list[0].id,
    "inspectionNo" : msg.payload.list[0].code,
    "locationId" : msg.payload.list[0].locationId,
    "locationName": msg.payload.list[0].locationName,
    //"objective": msg.payload.list[0].objective,
    //"scope": msg.payload.list[0].scope,
    "mainInspector": msg.payload.list[0].mainInspectorName,
    "secondaryInspector": msg.payload.list[0].secondaryInspectorName,
    "startDate": msg.payload.list[0].startDate,
    "endDate": msg.payload.list[0].endDate,
    "locale": msg.locale || "es"
};

msg.siteVisitId = msg.payload.list[0].id

return msg;

msg.entity = "InspectedProvider";
msg.entityData = {
    "id" : msg.providerId
    };
msg.entitySelect = "serviceProviderId,serviceProviderName"
return msg;

if (!msg.payload || !msg.payload.list || msg.payload.list.length === 0) {
    // An unknown /provider makes the InspectedProvider query come back empty. Indexing
    // list[0] here threw a TypeError that the catch could only report after the response
    // had already gone out, which left the flow answering ERR_HTTP_HEADERS_SENT until a
    // restart. Fail with a message instead.
    node.error("No inspected provider found for id: " + msg.providerId, msg);
    return null;
}
msg.inspectionPlan["provider"] = {
    "id" : msg.payload.list[0].serviceProviderId,
    "name" : msg.payload.list[0].serviceProviderName
};

return msg;

var err = msg.error;
var message = (err && err.message) ? err.message
    : (typeof err === "string" && err) ? err
    : (typeof msg.payload === "string" && msg.payload) ? msg.payload
    : "Request failed";
msg.payload = { success: false, error: message };
return msg;

// Upstream 4xx/5xx are delivered on the normal output; raise them so the flow's
// catch handler returns the error envelope instead of a 200 with the error body.
var status = parseInt(msg.statusCode, 10);
if (status >= 400) {
    var body = (typeof msg.payload === "string") ? msg.payload
        : (msg.payload && msg.payload.error) ? msg.payload.error : "";
    node.error("HTTP " + status + (body ? ": " + body : ""), msg);
    return null;
}
return msg;

// Deployment settings. The http request node renders its URL with mustache
// against msg only, and mustache HTML-escapes {{ }} values, so the base URLs
// are injected as msg properties and referenced with triple braces {{{ }}}.
msg.atrocoreBaseUrl = env.get("ATROCORE_BASE_URL") || "http://atro-web/api/v1";
msg.alfrescoBaseUrl = env.get("ALFRESCO_BASE_URL") || "http://proxy:8080/alfresco";
var timeout = parseInt(env.get("HTTP_REQUEST_TIMEOUT_MS"), 10);
if (timeout > 0) { msg.requestTimeout = timeout; }
return msg;

// Answer with what the caller asked for. The plan is already generated and the
// inspection status already set, so the response is just the generation result plus the
// status the flow settled on. (Before this node the response returned the updateEntity
// result, which is empty, so a successful call answered `200` with no body at all.)
var plan = msg.planGenerationResult;
var inspectionId = msg.inspectionId || (msg.inspectionPlan && msg.inspectionPlan.inspectionId) || null;
msg.payload = (plan && plan.generatedFile) ? plan : { status: "success" };
msg.payload.inspectionId = inspectionId;
msg.payload.inspectionStatus = "Planned";
return msg;
